        AssertRefused(AtmStatus.InsufficientFunds, Account(balance, 0), Full, result, dispenser);
    }

    [Theory]
    [InlineData(60, 60)]
    [InlineData(100, 100)] // pas de frais à 100
    [InlineData(115, 110)] // 110 + 5
